#include <time.h>
#include "pdss.h"
#include "memory.h"
#include "io.h"

/* Static functions (prototypes generated by tools/mkproto.py). */
static int alarm_clock_int(void);
static void sig_alarm_clock_int(int s) { (void)s; alarm_clock_int(); }	/* MODERN */
static int set_timer(int count, CELL *var);
/* PORT: forward declarations */



#define COUNT(H,M,S) ((H)*3600+(M)*60+(S))
#define HUGE	     0x7FFFFFFF

static int startup_day;
static int timer_last_count;
static int timer_next_count;
CELL *timer_table;


int initialize_timer(void)
{
    time_t clock;
    struct tm *tm;
    time(&clock);
    tm = localtime(&clock);
    startup_day = tm->tm_wday;
    timer_last_count = COUNT(tm->tm_hour, tm->tm_min, tm->tm_sec);
    timer_next_count = HUGE;
    AllocCell(timer_table);
    SetAll(timer_table, ATOM, NIL, MRBOFF);
    signal(PDSS_SIGALRM, sig_alarm_clock_int);
    if(option_alarm_clock_sw) pdss_alarm(1);
    return 0;
}

static int alarm_clock_int(void)
{
    time_t clock;
    struct tm *tm;
    int now;
    if(option_alarm_clock_sw) pdss_alarm(1);
    time(&clock);
    tm = localtime(&clock);
    now = COUNT(tm->tm_hour, tm->tm_min, tm->tm_sec);
    now += (tm->tm_wday-startup_day)*24*60*60;
    if(tm->tm_wday < startup_day) now += 7*24*60*60;
    if(timer_next_count <= now) SetAlarmIntFlag();
    timer_last_count = now;
#ifdef STATISTICS_SECOND
    STATISTICS_SECOND;
#endif
    return 0;
}

int timer_wakeup_goal(void)
{
    CELL *p, *q;
    int count;
    PDSS_SIGMASK mask;
    pdss_sig_block(PDSS_SIGALRM, &mask);
    timer_next_count = HUGE;
    p = timer_table;
    while(Typeof(p) == VECTOR){
	q = Objectof(p)+1;
	count = Valueof(q+1);
	if(count <= timer_last_count){
	    active_unify_with_integer(q+2, timer_last_count);
	    *p = *q;
	}else{
	    if(count < timer_next_count) timer_next_count = count;
	    p = q;
	}
    }
    pdss_sig_restore(&mask);
    return 0;
}

int is_there_goal_waiting_for_timer(void)
{
    if(Typeof(timer_table) == VECTOR){
	return(YES);
    }else{
	return(NO);
    }
}


int set_timer_on_after(int count, CELL *var)
{
    time_t clock;
    struct tm *tm;
    time(&clock);
    tm = localtime(&clock);
    set_timer(COUNT(tm->tm_hour, tm->tm_min, tm->tm_sec)+count, var);
    return 0;
}

int set_timer_on_at(int count, CELL *var)
{
    while(count <= timer_last_count) count += 24*36*36;
    set_timer(count, var);
    return 0;
}

static int set_timer(int count, CELL *var)
{
    CELL *p;
    PDSS_SIGMASK mask;
    pdss_sig_block(PDSS_SIGALRM, &mask);
    if(count <= timer_last_count || !option_alarm_clock_sw){
	active_unify_with_integer(var, timer_last_count);
    }else{
	AllocVector2(p, 3);
	*(p+1) = *timer_table;
	SetAll(p+2, INT, count, MRBOFF);
	*(p+3) = *var;
	SetAll(timer_table, VECTOR, p, MRBOFF);
	if(count < timer_next_count) timer_next_count = count;
    }
    pdss_sig_restore(&mask);
    return 0;
}

int get_time_count(void)
{
    time_t clock;
    struct tm *tm;
    time(&clock);
    tm = localtime(&clock);
    return(COUNT(tm->tm_hour, tm->tm_min, tm->tm_sec));
}
